// signalfd_thread_group: a SIGCHLD generated by one thread's fork()+_exit()
// must be observable via a signalfd read on a DIFFERENT thread of the same
// process -- not just the forking thread's own per-thread signal queue.
//
// kernel/exit.c resolves the target of a child's SIGCHLD as
// `leader->parent`, the specific task object that called fork() to create
// it. Historically kernel/signal.c then delivered straight into that one
// task's own `pending`/`queue` (locked by sighand->lock), and
// signalfd_poll/signalfd_read/receive_signals only ever drained `current`'s
// own queue. Real Linux instead delivers a process-directed signal like
// SIGCHLD into the whole thread group's shared_pending: any sibling thread
// with it unblocked can dequeue it, regardless of which specific thread
// happened to call fork(). A dedicated "reaper" thread that never forks --
// just opens a signalfd and polls it, the common pattern for an event-loop
// based process supervisor -- must still see the notification.
//
// This is a regression test for kernel/signal.c's shared `sighand->queue`/
// `sighand->pending` (see send_signal_to_process / deliver_signal_to_group_locked)
// and the corresponding signalfd_poll/signalfd_read/receive_signals/
// signal_take_next_locked changes that drain it, not just the receiving
// task's own per-thread queue.
//
// Unfixed: the forker thread's child delivers SIGCHLD into the forker task's
// own queue; the reaper thread's poll() on the signalfd never sees it and
// times out. Fixed: the SIGCHLD lands in the process's shared queue and the
// reaper's poll()+read() succeed promptly, with the correct child pid and
// CLD_EXITED code round-tripped through the shared siginfo.

#define _GNU_SOURCE

#include <errno.h>
#include <poll.h>
#include <pthread.h>
#include <signal.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/signalfd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

#include "test_common.h"

#define POLL_TIMEOUT_MS 3000

static int g_sigfd = -1;
static atomic_int g_child_pid;
static atomic_int g_reaper_saw_signal;
static atomic_int g_reaper_pid_match;
static atomic_int g_reaper_code_match;
static atomic_int g_reaper_errno;

static void on_alarm(int sig) {
    (void) sig;
    static const char msg[] =
        "signalfd_thread_group: FAIL timeout (reaper thread never woke)\n";
    write(2, msg, sizeof(msg) - 1);
    _exit(1);
}

static void *reaper_thread(void *arg) {
    (void) arg;
    struct pollfd pfd = { .fd = g_sigfd, .events = POLLIN };
    int n = poll(&pfd, 1, POLL_TIMEOUT_MS);
    if (n <= 0) {
        atomic_store(&g_reaper_errno, n < 0 ? errno : ETIMEDOUT);
        return NULL;
    }
    struct signalfd_siginfo si;
    ssize_t r = read(g_sigfd, &si, sizeof si);
    if (r != (ssize_t) sizeof si) {
        atomic_store(&g_reaper_errno, r < 0 ? errno : EIO);
        return NULL;
    }
    atomic_store(&g_reaper_saw_signal, 1);
    atomic_store(&g_reaper_pid_match, (int) si.ssi_pid == atomic_load(&g_child_pid));
    atomic_store(&g_reaper_code_match, (int) si.ssi_code == CLD_EXITED);
    return NULL;
}

static void *forker_thread(void *arg) {
    (void) arg;
    pid_t pid = fork();
    if (pid == 0)
        _exit(0);
    if (pid < 0) {
        failf("signalfd_thread_group fork", 0, 0, 0, 0, 0, 0);
        return NULL;
    }
    atomic_store(&g_child_pid, (int) pid);
    int status = 0;
    waitpid(pid, &status, 0);
    return NULL;
}

static void test_cross_thread_signalfd(void) {
    sigset_t mask;
    sigemptyset(&mask);
    sigaddset(&mask, SIGCHLD);
    // The mask is per-thread but shared at creation time: block it here,
    // before spawning either helper thread, so both inherit it blocked.
    if (sigprocmask(SIG_BLOCK, &mask, NULL) != 0) {
        failf("signalfd_thread_group sigprocmask", 0, 0, 0, 0, 0, 0);
        return;
    }

    g_sigfd = signalfd(-1, &mask, SFD_CLOEXEC);
    if (g_sigfd < 0) {
        failf("signalfd_thread_group signalfd", 0, 0, 0, 0, 0, 0);
        return;
    }

    pthread_t reaper, forker;
    if (pthread_create(&reaper, NULL, reaper_thread, NULL) != 0) {
        failf("signalfd_thread_group pthread_create_reaper", 0, 0, 0, 0, 0, 0);
        return;
    }
    // Give the reaper a head start into poll() before the forker races ahead.
    // Not required for correctness (the signal sits in the queue either way
    // until dequeued), just makes a pass unambiguous rather than a lucky race.
    usleep(20 * 1000);
    if (pthread_create(&forker, NULL, forker_thread, NULL) != 0) {
        failf("signalfd_thread_group pthread_create_forker", 0, 0, 0, 0, 0, 0);
        return;
    }

    pthread_join(forker, NULL);
    pthread_join(reaper, NULL);

    test_logf("child_pid=%d saw_signal=%d pid_match=%d code_match=%d reaper_errno=%d\n",
              atomic_load(&g_child_pid), atomic_load(&g_reaper_saw_signal),
              atomic_load(&g_reaper_pid_match), atomic_load(&g_reaper_code_match),
              atomic_load(&g_reaper_errno));

    if (!atomic_load(&g_reaper_saw_signal)) {
        failf("signalfd_thread_group no_cross_thread_signal",
              (uint64_t) atomic_load(&g_reaper_errno), 0, 0, 0, 0, 0);
        return;
    }
    if (!atomic_load(&g_reaper_pid_match)) {
        failf("signalfd_thread_group pid_mismatch",
              (uint64_t) atomic_load(&g_child_pid), 0, 0, 0, 0, 0);
    }
    if (!atomic_load(&g_reaper_code_match)) {
        failf("signalfd_thread_group code_mismatch", 0, 0, 0, 0, 0, 0);
    }
}

int main(int argc, char **argv) {
    test_init(argc, argv);
    signal(SIGALRM, on_alarm);
    alarm(10);
    test_cross_thread_signalfd();
    return finish_suite("signalfd_thread_group");
}
